def transform(grid):
    h, w = len(grid), len(grid[0])
    barrier = next(
        (r for r, row in enumerate(grid)
         if row[0] != 0 and all(x == row[0] for x in row)),
        None
    )
    if barrier is None:
        return [row[:] for row in grid]

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or r == barrier or (r, c) in seen:
                continue
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for nr, nc in ((cr-1, cc), (cr+1, cc), (cr, cc-1), (cr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            nr != barrier and (nr, nc) not in seen and
                            grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    downward = barrier > h // 2
    if downward:
        objects.sort(key=lambda obj: max(r for r, c in obj[1]), reverse=True)
    else:
        objects.sort(key=lambda obj: min(r for r, c in obj[1]))

    out = [[0] * w for _ in range(h)]
    out[barrier] = grid[barrier][:]
    occupied = {(barrier, c) for c in range(w)}

    for color, cells in objects:
        dr = 1 if downward else -1
        while True:
            shifted = [(r + dr, c) for r, c in cells]
            if any(r < 0 or r >= h or (r, c) in occupied for r, c in shifted):
                break
            cells = shifted
        for r, c in cells:
            out[r][c] = color
            occupied.add((r, c))
    return out
